<template><section class="transition-invitation" aria-label="Portal invitation and assigned forms"><h3>Portal invitation &amp; forms</h3><p>Review the authorized recipient, language and assigned forms before sending the transition email. Pending forms receive reminders every 48 hours when the recipient’s email preferences allow them.</p><ClientAdultPortalInvite v-if="personalAccountOnly" :agency-id="Number(agencyId)" :client-id="Number(clientId)" prepare-only :patient-info-pending="patientInfoPending" @edit-contact="emit('review-patient-info')" @updated="clearPreview" @busy="accessBusy" /><ClientPortalAccessEditor v-else :agency-id="agencyId" :client-id="clientId" :refresh-key="refreshKey" :patient-info-pending="patientInfoPending" @review-patient-info="emit('review-patient-info')" @saved="clearPreview" @busy="accessBusy" /><button type="button" :disabled="busy || loading" @click="load">{{ loading?'Preparing preview…':'Preview transition invitation' }}</button><p v-if="!sendingEnabled" role="status">Portal access can be saved independently. Finish importing the filled record sections before sending the invitation.</p><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><template v-if="preview"><p v-if="!preview.recipients?.length" role="status">No eligible portal account was found. Finish preparing the intended account above, then preview again.</p><p v-if="!preview.launchEnabled">Migration invitations are staged. The rollout setting must be enabled before sending.</p><ul v-if="preview.skipped?.length"><li v-for="item in preview.skipped" :key="item.clientId">{{ item.reason }}</li></ul><article v-for="recipient in preview.recipients" :key="recipient.key"><h4>{{recipient.name}} · {{recipient.email}}</h4><p>Language: <strong>{{recipient.language==='es'?'Spanish':'English'}}</strong></p><p v-if="recipient.billingOnly">This account receives payment access. Treatment records and clinical documents remain restricted.</p><ul><li v-for="form in recipient.forms" :key="`${form.kind}:${form.title}`"><strong>{{form.title}}</strong> · {{form.assigned?'Attached in portal':form.available?'Will attach before sending':'Needs setup in this language'}}</li></ul><p v-if="recipient.blockedReason" role="alert">{{recipient.blockedReason}}</p><details><summary>Preview email: {{recipient.email?.subject || recipient.emailPreview?.subject || 'Transition invitation'}}</summary><h5>{{recipient.emailPreview?.subject || recipient.email?.subject}}</h5><pre>{{recipient.emailPreview?.text || recipient.email?.text}}</pre><p>The actual email contains the recipient’s secure setup or sign-in link.</p></details><label class="check"><input v-model="confirmed[recipient.key]" type="checkbox" :disabled="busy || !!recipient.blockedReason" /> I reviewed this account’s access, language and forms.</label><button v-if="recipient.needsPreparation" type="button" :disabled="busy || !sendingEnabled || !confirmed[recipient.key] || !!recipient.blockedReason" @click="prepare(recipient)">Attach these forms to the portal</button><button v-else type="button" :disabled="busy || !sendingEnabled || !confirmed[recipient.key] || !!recipient.blockedReason || !preview.launchEnabled || !!results[recipient.key]" @click="send(recipient)">Send portal invitation</button><p v-if="results[recipient.key]" role="status">{{results[recipient.key]}}</p></article></template></section></template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import sharedApi from '../../services/api';
import {transitionRequestScope} from '../../utils/transitionRequestScope';
const api={...sharedApi,...transitionRequestScope(sharedApi,()=>props.agencyId)};import ClientAdultPortalInvite from './ClientAdultPortalInvite.vue';
import ClientPortalAccessEditor from './ClientPortalAccessEditor.vue';
const props=defineProps({personalAccountOnly:Boolean,patientInfoPending:Boolean,clientId:[String,Number],agencyId:[String,Number],refreshKey:[String,Number],sendingEnabled:{type:Boolean,default:true}});const emit=defineEmits(['busy','sent','review-patient-info']);const preview=ref(null),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),confirmed=ref({}),results=ref({});let seq=0;
const body=()=>({agencyId:Number(props.agencyId),clientId:Number(props.clientId)});
function accessBusy(value){busy.value=value;emit('busy',value);}
function scopedPreview(data){return props.personalAccountOnly?{...data,recipients:(data.recipients||[]).filter(recipient=>recipient.relationshipType==='self')}:data;}
function clearPreview(){++seq;loading.value=false;preview.value=null;confirmed.value={};notice.value='';error.value='';}
async function load(){const own=++seq;loading.value=true;error.value='';notice.value='';confirmed.value={};try{const {data}=await api.post('/portal-migration/staff/transition-preview',body());if(own===seq)preview.value=scopedPreview(data);}catch(e){if(own===seq)error.value=e.response?.data?.error?.message||'The portal invitation could not be previewed.';}finally{if(own===seq)loading.value=false;}}
async function prepare(recipient){if(busy.value||!props.sendingEnabled)return;const own=seq;busy.value=true;emit('busy',true);error.value='';try{const {data}=await api.post('/portal-migration/staff/transition-prepare',{...body(),recipientKey:recipient.key});if(own===seq){preview.value=scopedPreview(data);notice.value='Forms attached. Review the email and confirm before sending.';confirmed.value={};}}catch(e){if(own===seq)error.value=e.response?.data?.error?.message||'The portal forms could not be attached.';}finally{busy.value=false;emit('busy',false);}}
async function send(recipient){if(busy.value||!props.sendingEnabled)return;const own=seq;busy.value=true;emit('busy',true);error.value='';try{const {data}=await api.post('/portal-migration/staff/transition-send',{...body(),recipientKey:recipient.key});if(own!==seq)return;const delivery=data.delivery||{};results.value[recipient.key]=delivery.alreadyRecorded?'This invitation was already processed. Review email history before resending.':delivery.queued||delivery.pendingApproval?'Queued for email approval':delivery.redirected?'Redirected to the configured test inbox':delivery.blocked||delivery.skipped?'Not sent: '+(delivery.reason||'delivery held by notification settings'):delivery.id?'Invitation sent. Portal sign-ins and activity appear in the client’s Portal tab.':'Delivery is unconfirmed. Review email history before retrying.';emit('sent',data);}catch(e){if(own===seq)error.value=e.response?.data?.error?.message||'Delivery is unconfirmed. Review email history before retrying.';}finally{busy.value=false;emit('busy',false);}}
watch(()=>[props.clientId,props.agencyId,props.refreshKey],()=>{clearPreview();results.value={};});onBeforeUnmount(()=>{seq++;});
</script>
<style scoped>.transition-invitation{padding:18px;border:1px solid #b6c9dc;border-radius:10px;margin-top:22px}.transition-invitation article{padding:18px 0;border-top:1px solid #d5e1ed;margin-top:18px}.transition-invitation button{padding:10px 14px;font:inherit;margin-right:8px}.transition-invitation pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.6}.transition-invitation .check{display:flex;gap:8px;margin:16px 0}.transition-invitation [role=alert]{color:#a12727}</style>
